const svg=(body,cls='')=>`<svg class="${cls}" viewBox="0 0 300 180" aria-hidden="true" fill="none" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
export function sigil(cls=''){return `<svg class="sigil ${cls}" viewBox="0 0 400 380" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="1"><path d="M200 20 353 190 200 360 47 190Z"/><path d="m200 20 80 170-80 170-80-170Zm0 0v340M47 190h306M47 190l153-65 153 65-153 65Z"/><path d="m200 125-80 65 80 65 80-65Z"/></g><g fill="currentColor"><circle cx="200" cy="20" r="3"/><circle cx="353" cy="190" r="3"/><circle cx="200" cy="360" r="3"/><circle cx="47" cy="190" r="3"/></g></svg>`;}
export function art(id){let dots=Array.from({length:12},(_,i)=>{let a=i*Math.PI/6;return [150+Math.sin(a)*61,90-Math.cos(a)*61];});if(id==='virus')return svg(`<circle cx="150" cy="90" r="61" stroke="currentColor" opacity=".25"/>${dots.map(([x,y],i)=>`<path d="M150 90 ${x} ${y}" stroke="currentColor" opacity=".14"/><circle cx="${x}" cy="${y}" r="${i===2||i===7?9:5}" fill="${i===2||i===7?'var(--red)':'currentColor'}" opacity="${i===2||i===7?1:.5}"/>`).join('')}<path d="m150 62 25 28-25 28-25-28Z" stroke="var(--red)"/><circle cx="150" cy="90" r="4" fill="var(--red)"/>`);
if(id==='race')return svg(`<path d="M55 131h44V93h49v40h49V79h47V42" stroke="currentColor" stroke-width="2"/>${[[55,131],[99,93],[148,133],[197,79],[244,42]].map(([x,y],i)=>`<rect x="${x-10}" y="${y-10}" width="20" height="20" rx="2" fill="${i===3?'var(--red)':'var(--paper)'}" stroke="${i===3?'var(--red)':'currentColor'}"/>`).join('')}<path d="M46 49h34v34H46zM52 56h4m13 0h4M52 76h4m13 0h4" stroke="currentColor" stroke-width="2"/>`);
if(id==='number')return svg(`<g transform="rotate(-12 100 90)"><rect x="65" y="37" width="75" height="110" rx="5" fill="var(--paper)" stroke="currentColor" opacity=".6"/><text x="102" y="112" text-anchor="middle" fill="currentColor" font-family="Georgia" font-size="56">?</text></g><g transform="rotate(8 180 90)"><rect x="139" y="30" width="84" height="117" rx="5" fill="var(--paper)" stroke="currentColor"/><text x="181" y="111" text-anchor="middle" fill="var(--red)" font-family="Georgia" font-size="56">?</text></g>`);
if(id==='hex')return svg(Array.from({length:19},(_,i)=>{let rows=[3,4,5,4,3],row=0,idx=i;while(idx>=rows[row])idx-=rows[row++];let x=150+(idx-(rows[row]-1)/2)*26,y=35+row*27;return `<path d="m${x} ${y-15} 13 7.5v15l-13 7.5-13-7.5v-15Z" stroke="${i===9?'var(--red)':'currentColor'}" opacity="${i===9?1:.4}"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="currentColor" font-family="monospace" font-size="10">${String.fromCharCode(65+i)}</text>`;}).join(''));
if(id==='morris')return svg(`<g stroke="currentColor" opacity=".5"><path d="M75 20h150v140H75ZM97 42h106v96H97ZM119 64h62v52h-62ZM150 20v44m0 52v44M75 90h44m62 0h44"/></g><circle cx="75" cy="20" r="7" fill="currentColor"/><circle cx="150" cy="20" r="7" fill="var(--red)"/><circle cx="225" cy="20" r="7" fill="currentColor"/><circle cx="97" cy="90" r="7" fill="currentColor"/><circle cx="150" cy="116" r="7" fill="var(--red)"/>`);
if(id==='equation')return svg(`<text x="150" y="105" text-anchor="middle" font-family="Georgia" font-size="48" fill="currentColor">7<tspan fill="var(--red)"> + </tspan>9<tspan fill="var(--red)"> ÷ </tspan>3</text><path d="M55 127h190" stroke="currentColor" opacity=".25"/><text x="150" y="151" text-anchor="middle" font-family="monospace" font-size="9" letter-spacing="4" fill="currentColor">LOW / HIGH</text>`);
if(id==='scale')return svg(`<path d="m150 40 0 106m-29 25h58L150 143Zm-62-29-29 0 0-62m124 62 29 0 0-62M62 61l176-20M48 114h57l-9 16H57Zm149 0h57l-9 16h-39Z" stroke="currentColor" stroke-width="2"/><path d="M72 91h15v21H72Zm142-7h17v28h-17Z" fill="var(--red)"/><circle cx="150" cy="51" r="5" fill="currentColor"/>`);
if(id==='words')return svg(`<g font-family="Georgia" font-size="24" text-anchor="middle" fill="currentColor">${'PLAN'.split('').map((l,i)=>`<rect x="${81+i*34}" y="${105-i*21}" width="32" height="33" rx="2" stroke="currentColor" fill="var(--paper)"/><text x="${97+i*34}" y="${131-i*21}">${l}</text>`).join('')}</g><path d="M62 151h178" stroke="currentColor" opacity=".25"/>`);
if(id==='zoo')return svg(`<g font-family="Georgia" font-size="27" text-anchor="middle" fill="currentColor">${'SLMPE'.split('').map((l,i)=>`<rect x="${47+i*43}" y="${i%2?77:48}" width="39" height="57" rx="19" stroke="${i===2?'var(--red)':'currentColor'}"/><text x="${66+i*43}" y="${i%2?114:85}" fill="${i===2?'var(--red)':'currentColor'}">${l}</text>`).join('')}</g>`);
if(id==='memory')return svg(`<path d="M62 36h69v95H62ZM96 36v95M62 83h69m30-45h79v58h-79Zm-22 82h112m-102 0v39m92-39v39" stroke="currentColor" opacity=".6"/><path d="M164 104h45v15h-45Z" fill="var(--red)"/><circle cx="203" cy="66" r="14" stroke="currentColor"/><path d="M203 55v12h8" stroke="currentColor"/>`);
if(id==='montage')return svg(`<rect x="93" y="21" width="114" height="139" rx="56" stroke="currentColor" opacity=".3"/><path d="M107 145q0-37 43-37t43 37" fill="currentColor" opacity=".15"/><ellipse cx="150" cy="77" rx="28" ry="37" stroke="currentColor"/><path d="M124 66q1-44 29-31 28 0 27 33l-31-12Z" fill="currentColor"/><circle cx="139" cy="76" r="2" fill="currentColor"/><circle cx="161" cy="76" r="2" fill="currentColor"/><path d="M140 91q10 8 20 0" stroke="var(--red)" stroke-width="2"/>`);
if(id==='gomoku')return svg(`<path d="${[60,90,120,150,180,210,240].map(x=>`M${x} 30v120`).join('')}${[30,60,90,120,150].map(y=>`M60 ${y}h180`).join('')}" stroke="currentColor" opacity=".15"/>${[[90,60],[120,90],[150,120],[180,150]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="9" fill="currentColor"/>`).join('')}<circle cx="180" cy="90" r="9" fill="var(--red)"/>`);
return svg(`<g>${Array.from({length:16},(_,i)=>`<rect x="${86+i%4*33}" y="${27+Math.floor(i/4)*33}" width="30" height="30" rx="2" fill="${id==='grass'?['#72816a','#a7af99','#b0baa2','#687b63'][Math.floor(i/4)]:i%5===0?'var(--red)':'currentColor'}" opacity="${id==='grass'?1:.2+i%3*.12}"/>`).join('')}</g>`);
}
export const logo=`<svg viewBox="0 0 40 48" width="34" height="40" fill="none" aria-hidden="true"><path d="M20 2 38 24 20 46 2 24Z" stroke="currentColor" stroke-width="1.5"/><path d="M20 2v44M2 24h36L20 16 2 24l18 8 18-8M20 2 11 24l9 22 9-22Z" stroke="currentColor" stroke-width="1"/></svg>`;
